const V="smartcash-v1.1", CORE=["./", "index.html", "manifest.webmanifest", "icon-192.png", "icon-512.png", "favicon.svg", "js/audit.js", "js/cash.js", "js/config.js", "js/core.js", "js/cust.js", "js/data.js", "js/gateway.js", "js/geo.js", "js/google.js", "js/guard.js", "js/i18n/ar.js", "js/i18n/en.js", "js/intro.js", "js/lazy.js", "js/live.js", "js/motion.js", "js/pay.js", "js/plans.js", "js/plans6.js", "js/security.js", "js/setup.js", "js/views.js", "js/views2.js", "js/views3.js", "vendor/hairline.mjs"];
self.addEventListener("install",e=>{e.waitUntil(caches.open(V).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting()))});
self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==V).map(x=>caches.delete(x)))).then(()=>self.clients.claim()))});
self.addEventListener("fetch",e=>{ const r=e.request; if(r.method!=="GET") return; if(new URL(r.url).origin!==location.origin && !/^https:\/\/fonts\.(googleapis|gstatic)\.com\//.test(r.url)) return;
  e.respondWith(caches.match(r).then(hit=>{ const net=fetch(r).then(res=>{ if(res&&(res.ok||res.type==="opaque")){ const cp=res.clone(); caches.open(V).then(c=>c.put(r,cp)) } return res }).catch(()=>hit||(r.mode==="navigate"?caches.match("index.html"):undefined)); return hit||net })) });
